export const getExportEventExcelUrl = (id: number,) => {




  return `/api/events/${id}/export`
}

/**
 * @summary Export event attendees as ISC2-formatted Excel file
 */
export const exportEventExcel = async (id: number, options?: RequestInit): Promise<Blob> => {

  return customFetch<Blob>(getExportEventExcelUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}





export const getExportEventExcelQueryKey = (id: number,) => {
    return [
    `/api/events/${id}/export`
    ] as const;
    }


export const getExportEventExcelQueryOptions = <TData = Awaited<ReturnType<typeof exportEventExcel>>, TError = ErrorType<ErrorResponse>>(id: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof exportEventExcel>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getExportEventExcelQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof exportEventExcel>>> = ({ signal }) => exportEventExcel(id, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof exportEventExcel>>, TError, TData> & { queryKey: QueryKey }
}

export type ExportEventExcelQueryResult = NonNullable<Awaited<ReturnType<typeof exportEventExcel>>>
export type ExportEventExcelQueryError = ErrorType<ErrorResponse>


/**
 * @summary Export event attendees as ISC2-formatted Excel file
 */

export function useExportEventExcel<TData = Awaited<ReturnType<typeof exportEventExcel>>, TError = ErrorType<ErrorResponse>>(
 id: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof exportEventExcel>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getExportEventExcelQueryOptions(id,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







